CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, default_locale text NOT NULL DEFAULT 'fr' CHECK(default_locale IN ('ar','fr','en')));
CREATE TABLE warehouses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, code text NOT NULL, name text NOT NULL, UNIQUE(org_id,code));
CREATE TABLE staff_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, email text NOT NULL UNIQUE, name text NOT NULL, role text NOT NULL CHECK(role IN ('owner','manager','warehouse','sales','buyer','curator','auditor','accountant')), password_hash text NOT NULL, locale text NOT NULL DEFAULT 'fr' CHECK(locale IN ('ar','fr','en')), mfa_secret text, mfa_last_step bigint, active boolean NOT NULL DEFAULT true, warehouse_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES staff_users, csrf_token text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, last_seen timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, email text NOT NULL, name text NOT NULL, role text NOT NULL, warehouse_ids uuid[] NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, created_by uuid NOT NULL REFERENCES staff_users);
CREATE TABLE sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, origin text NOT NULL, license text NOT NULL, can_store boolean NOT NULL DEFAULT false, can_display boolean NOT NULL DEFAULT false, can_syndicate boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'REVIEW_REQUIRED', checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, make text NOT NULL, model text NOT NULL, generation text NOT NULL, market text NOT NULL, year_from integer NOT NULL, year_to integer NOT NULL, engine text NOT NULL, fuel text NOT NULL, transmission text NOT NULL, body text NOT NULL, equipment text NOT NULL DEFAULT '', source_id uuid REFERENCES sources, external_id text, aliases jsonb NOT NULL DEFAULT '{}', CHECK(year_from<=year_to), UNIQUE(org_id,source_id,external_id));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, sku text NOT NULL, names jsonb NOT NULL, descriptions jsonb NOT NULL DEFAULT '{}', brand text NOT NULL, oem text NOT NULL DEFAULT '', barcode text NOT NULL DEFAULT '', category text NOT NULL, pack_size integer NOT NULL DEFAULT 1 CHECK(pack_size>0 AND pack_size<=10000), price_minor bigint NOT NULL CHECK(price_minor>=0), cost_minor bigint NOT NULL CHECK(cost_minor>=0), reorder_level integer NOT NULL DEFAULT 5 CHECK(reorder_level>=0), status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ACTIVE_INTERNAL','ARCHIVED')), translation_status jsonb NOT NULL DEFAULT '{"ar":"REVIEW_REQUIRED","fr":"REVIEW_REQUIRED","en":"REVIEW_REQUIRED"}', source_id uuid REFERENCES sources, search_text text NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,sku));
CREATE INDEX products_search_trgm ON products USING gin(search_text gin_trgm_ops);
CREATE INDEX products_org_sku ON products(org_id,sku);
CREATE TABLE product_identifiers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products, type text NOT NULL, raw_value text NOT NULL, normalized_value text NOT NULL, source_id uuid REFERENCES sources, UNIQUE(product_id,type,raw_value));
CREATE INDEX identifiers_lookup ON product_identifiers(normalized_value);
CREATE TABLE product_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products, mime text NOT NULL, bytes bytea NOT NULL, sha256 text NOT NULL, rights text NOT NULL, created_by uuid NOT NULL REFERENCES staff_users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fitments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products, vehicle_id uuid NOT NULL REFERENCES vehicles, status text NOT NULL DEFAULT 'REVIEW_REQUIRED' CHECK(status IN ('UNRESEARCHED','SOURCE_CLAIMED','REVIEW_REQUIRED','VERIFIED','CONFLICTED','REJECTED')), evidence text, source_id uuid REFERENCES sources, qualifiers text NOT NULL DEFAULT '', reviewed_by uuid REFERENCES staff_users, reviewed_at timestamptz, CHECK(status<>'VERIFIED' OR (reviewed_by IS NOT NULL AND evidence IS NOT NULL AND length(evidence)>10 AND source_id IS NOT NULL)), UNIQUE(product_id,vehicle_id));
CREATE TABLE suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, contact text NOT NULL DEFAULT '', lead_days integer NOT NULL DEFAULT 0 CHECK(lead_days>=0), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE supplier_items (supplier_id uuid NOT NULL REFERENCES suppliers, product_id uuid NOT NULL REFERENCES products, reference text NOT NULL, cost_minor bigint NOT NULL CHECK(cost_minor>=0), PRIMARY KEY(supplier_id,product_id));
CREATE TABLE purchase_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, supplier_id uuid NOT NULL REFERENCES suppliers, warehouse_id uuid NOT NULL REFERENCES warehouses, reference text NOT NULL, status text NOT NULL DEFAULT 'ORDERED' CHECK(status IN ('ORDERED','PART_RECEIVED','RECEIVED','CANCELLED')), created_by uuid NOT NULL REFERENCES staff_users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,reference));
CREATE TABLE purchase_lines (purchase_id uuid NOT NULL REFERENCES purchase_orders, product_id uuid NOT NULL REFERENCES products, quantity integer NOT NULL CHECK(quantity>0), received integer NOT NULL DEFAULT 0 CHECK(received>=0), cost_minor bigint NOT NULL CHECK(cost_minor>=0), PRIMARY KEY(purchase_id,product_id));
CREATE TABLE inventory_balances (org_id uuid NOT NULL REFERENCES organizations, product_id uuid NOT NULL REFERENCES products, warehouse_id uuid NOT NULL REFERENCES warehouses, on_hand integer NOT NULL DEFAULT 0, reserved integer NOT NULL DEFAULT 0, quarantine integer NOT NULL DEFAULT 0, damaged integer NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 0, PRIMARY KEY(product_id,warehouse_id), CHECK(on_hand>=0 AND reserved>=0 AND reserved<=on_hand AND quarantine>=0 AND damaged>=0));
CREATE TABLE business_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, kind text NOT NULL, reference text, actor_id uuid NOT NULL REFERENCES staff_users, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX receipt_reference_unique ON business_documents(org_id,reference) WHERE kind='RECEIPT';
CREATE TABLE stock_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, document_id uuid NOT NULL REFERENCES business_documents, product_id uuid NOT NULL REFERENCES products, warehouse_id uuid NOT NULL REFERENCES warehouses, kind text NOT NULL, on_hand_delta integer NOT NULL DEFAULT 0, reserved_delta integer NOT NULL DEFAULT 0, quarantine_delta integer NOT NULL DEFAULT 0, damaged_delta integer NOT NULL DEFAULT 0, actor_id uuid NOT NULL REFERENCES staff_users, request_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX movements_ledger ON stock_movements(product_id,warehouse_id);
CREATE TABLE reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, warehouse_id uuid NOT NULL REFERENCES warehouses, actor_id uuid NOT NULL REFERENCES staff_users, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','FULFILLED','RELEASED','EXPIRED')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reservation_lines (reservation_id uuid NOT NULL REFERENCES reservations, product_id uuid NOT NULL REFERENCES products, quantity integer NOT NULL CHECK(quantity>0), PRIMARY KEY(reservation_id,product_id));
CREATE TABLE sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, warehouse_id uuid NOT NULL REFERENCES warehouses, actor_id uuid NOT NULL REFERENCES staff_users, reservation_id uuid UNIQUE REFERENCES reservations, total_minor bigint NOT NULL CHECK(total_minor>=0), locale text NOT NULL CHECK(locale IN ('ar','fr','en')), status text NOT NULL DEFAULT 'COMPLETED', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sale_lines (sale_id uuid NOT NULL REFERENCES sales, product_id uuid NOT NULL REFERENCES products, sku text NOT NULL, names jsonb NOT NULL, quantity integer NOT NULL CHECK(quantity>0), price_minor bigint NOT NULL CHECK(price_minor>=0), returned integer NOT NULL DEFAULT 0 CHECK(returned>=0 AND returned<=quantity), PRIMARY KEY(sale_id,product_id));
CREATE TABLE returns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, sale_id uuid NOT NULL REFERENCES sales, product_id uuid NOT NULL REFERENCES products, warehouse_id uuid NOT NULL REFERENCES warehouses, quantity integer NOT NULL CHECK(quantity>0), reason text NOT NULL, status text NOT NULL DEFAULT 'QUARANTINE' CHECK(status IN ('QUARANTINE','SELLABLE','DAMAGED')), actor_id uuid NOT NULL REFERENCES staff_users, inspected_by uuid REFERENCES staff_users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stock_counts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, product_id uuid NOT NULL REFERENCES products, warehouse_id uuid NOT NULL REFERENCES warehouses, counted integer NOT NULL CHECK(counted>=0), expected integer NOT NULL, balance_version integer NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')), created_by uuid NOT NULL REFERENCES staff_users, approved_by uuid REFERENCES staff_users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency (org_id uuid NOT NULL REFERENCES organizations, actor_id uuid NOT NULL REFERENCES staff_users, key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(org_id,actor_id,key));
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, org_id uuid REFERENCES organizations, actor_id uuid REFERENCES staff_users, action text NOT NULL, object_id text, data jsonb NOT NULL DEFAULT '{}', request_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, kind text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, attempts integer NOT NULL DEFAULT 0, error_code text, UNIQUE(kind,aggregate_id));
CREATE TABLE event_deliveries (event_id uuid NOT NULL REFERENCES outbox_events, consumer text NOT NULL, delivered_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(event_id,consumer));
CREATE TABLE import_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations, source_id uuid NOT NULL REFERENCES sources, created_by uuid NOT NULL REFERENCES staff_users, status text NOT NULL DEFAULT 'PREVIEW' CHECK(status IN ('PREVIEW','COMMITTED','REVERTED')), rows jsonb NOT NULL, errors jsonb NOT NULL, checksum text NOT NULL, committed_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'IMMUTABLE_RECORD'; END $$;
CREATE TRIGGER immutable_movements BEFORE UPDATE OR DELETE ON stock_movements FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_documents BEFORE UPDATE OR DELETE ON business_documents FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
